        "type": "string",
        "description": "B2C (individuals) | B2B (business clients) | B2X (both) | X",
        "default": "B2C"
      },
      "registration_type": {
        "type": "string",
        "description": "One of REGISTRATION_TYPE_NO_VERIFICATION | _VERIFICATION | _CODE_IMMEDIATE_LOGIN_IMMEDIATE",
        "default": "REGISTRATION_TYPE_NO_VERIFICATION"
      },
      "level": {
        "type": "string",
        "description": "CLIENT | CUSTOMER | CONSUMER \u2014 defaults from usage_type (B2C\u2192CONSUMER, others\u2192CUSTOMER)"
      },
      "client_id": {
        "type": "string",
        "description": "Owning client_id (default 1 = SYSTEM)",
        "default": "1"
      },
      "client_type": {
        "type": "string",
        "description": "IND for individual consumers, BUS for business clients",
        "default": "INDV"
      },
      "business_type": {
        "type": "string",
        "description": "Business type code, default COMMON",
        "default": "COMMON"
      }
